// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _test(uint256 val) internal {
        try c.Initialized() {} catch { return; }
        bool ok = true;
        try c.SetMinSum(val) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }

    function testFuzz_test(uint256 val) public {
        _test(val);
    }

    receive() external payable {}
}
